$ErrorActionPreference = 'Stop'

$projectRoot = Split-Path -Parent $PSScriptRoot
$cssRoot = Join-Path $projectRoot 'css'
$outputPath = Join-Path $cssRoot 'site.css'
$sourceFiles = @(
    'reset.css',
    'theme.css',
    'typography.css',
    'layout.css',
    'navigation.css',
    'animation.css',
    'home.css',
    'responsive.css',
    'timeline.css',
    'projects.css',
    'updates.css',
    'about.css',
    'contact.css',
    'sectionTransitions.css'
)

$sections = @(
    '/* Generated by tools/build-css.ps1. Edit the component files, then rebuild. */'
)

foreach ($sourceFile in $sourceFiles) {
    $sourcePath = Join-Path $cssRoot $sourceFile
    if (-not (Test-Path -LiteralPath $sourcePath)) {
        throw "Missing CSS source: $sourcePath"
    }

    $sections += "`n/* ===== $sourceFile ===== */`n"
    $sections += [System.IO.File]::ReadAllText($sourcePath)
}

$content = ($sections -join "`n").TrimEnd() + "`n"
$utf8WithoutBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($outputPath, $content, $utf8WithoutBom)

Write-Host "Built $outputPath from $($sourceFiles.Count) stylesheets."
